import { FunnelChart } from '@dreadnought/ui/react';
const data = [{ id: 'visit', label: 'Визиты', value: 1000 }, { id: 'cart', label: 'Корзина', value: 400 }, { id: 'paid', label: 'Оплата', value: 100 }];
export function Example() { return <FunnelChart label="Путь к покупке" data={data} />; }

import { FunnelChart, useFunnelChart } from '@dreadnought/ui/react';
const data = [{id:'a',label:'Визиты',value:100},{id:'b',label:'Оплата',value:10}];
function Controls() { const {page} = useFunnelChart(); return <button disabled={page.page === page.count} onClick={() => page.change(page.page + 1)}>Следующая страница</button>; }
export function Example() { return <FunnelChart label="Распределение" data={data} pageSize={1}><Controls /><FunnelChart.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</FunnelChart.Plot><FunnelChart.Table /><FunnelChart.Pagination /><FunnelChart.Empty /></FunnelChart>; }
